declaration:
FUNCTION_BLOCK FB_DWordEdgeDetection
    VAR_INPUT
        value : DWORD;
    END_VAR

    VAR_OUTPUT
        hasChanged : BOOL;
        hasRisingEdges : BOOL;
        risingBits : DWORD;
        noOfRisingBits : USINT;
        hasFallingEdges : BOOL;
        fallingBits : DWORD;
        noOfFallingBits : USINT;
    END_VAR

    VAR
        oldValue : DWORD;
    END_VAR
END_FUNCTION_BLOCK

implementation:
(* Initialize old value on first call *)
IF NOT oldValue THEN
    oldValue := value;
END_IF;

(* Check for changes *)
hasChanged := value <> oldValue;

(* Detect rising edges *)
risingBits := (value AND NOT oldValue);
hasRisingEdges := risingBits <> 0;
noOfRisingBits := BYTE#0;
FOR i := 0 TO 31 DO
    IF risingBits[i] THEN
        noOfRisingBits := noOfRisingBits + 1;
    END_IF;
END_FOR;

(* Detect falling edges *)
fallingBits := (NOT value AND oldValue);
hasFallingEdges := fallingBits <> 0;
noOfFallingBits := BYTE#0;
FOR i := 0 TO 31 DO
    IF fallingBits[i] THEN
        noOfFallingBits := noOfFallingBits + 1;
    END_IF;
END_FOR;

(* Update old value *)
oldValue := value;
